import { useEffect, useMemo, useState } from "react";
import AppLayout from "@/components/AppLayout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { trpc } from "@/lib/trpc";
import { toast } from "sonner";
import { BarChart3, Bell, BriefcaseBusiness, Building2, Check, CreditCard, FileSignature, FileText, History, Layers3, Loader2, Mail, PackageOpen, Palette, Pencil, Plus, Printer, Save, Send, Settings2, Trash2, Upload, X } from "lucide-react";

const api = (trpc as any).commercial;
type Tab = "overview" | "updates" | "proposals" | "contracts" | "portfolio" | "plans" | "features" | "structure" | "brand" | "finance";

const statusLabel: Record<string, string> = {
  lead: "Lead", negociacao: "Negociação", proposta_enviada: "Proposta enviada",
  aguardando_retorno: "Aguardando retorno", aprovada: "Aprovada", reprovada: "Reprovada", convertida: "Convertida",
  novo_lead:"Novo lead",em_contato:"Em contato",reuniao_agendada:"Reunião agendada",reuniao_realizada:"Reunião realizada",proposta_em_elaboracao:"Proposta em elaboração",follow_up:"Follow-up",contrato_em_assinatura:"Contrato em assinatura",perdida:"Perdida",pausada:"Pausada",
};

function brl(value: any) { return Number(value || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" }); }
function ids(value: any): number[] { try { return JSON.parse(value || "[]").map(Number); } catch { return []; } }
function commercialPrice(plan:any,employees:number,bands:any[]){const base=Number(plan.fixed_monthly_price||0)+Number(plan.price_per_employee||0)*employees;const band=bands.find((item:any)=>employees>=Number(item.min_employees)&&employees<=Number(item.max_employees));const discounted=base*(1-Number(band?.discount_pct||0)/100);return Math.max(discounted,Number(plan.minimum_monthly||0),Number(band?.minimum_monthly||0));}

export function CommercialWorkspace() {
  const [tab, setTab] = useState<Tab>("overview");
  const ctxQ = api.context.useQuery();
  const featuresQ = api.listFeatures.useQuery();
  const plansQ = api.listPlans.useQuery();
  const proposalsQ = api.listProposals.useQuery();
  const structureQ = api.listCatalogStructure.useQuery();
  const updatesQ = api.platformUpdates.useQuery();
  const portfolioQ = api.portfolioCatalog.useQuery();
  const financeQ = api.finance.useQuery(undefined, { enabled: tab === "finance" });
  const contractsQ = api.contractWorkspace.useQuery(undefined, { enabled: tab === "contracts" });
  const [planModal, setPlanModal] = useState<any>(null);
  const [proposalModal, setProposalModal] = useState<any>(null);
  const [featureModal, setFeatureModal] = useState<any>(null);
  const [addonModal, setAddonModal] = useState<any>(null);
  const [contractModal, setContractModal] = useState<any>(null);
  const [editContractModal, setEditContractModal] = useState<any>(null);
  const [deleteContract, setDeleteContract] = useState<any>(null);
  const [sendContract, setSendContract] = useState<any>(null);
  const [templateModal, setTemplateModal] = useState<any>(null);
  const [clauseModal, setClauseModal] = useState<any>(null);
  const [uploadContract, setUploadContract] = useState<any>(null);
  const [activityProposal, setActivityProposal] = useState<any>(null);
  const [sendConfirm, setSendConfirm] = useState<any>(null);
  const [brand, setBrand] = useState<any>(null);

  useEffect(() => { if (ctxQ.data?.brand) setBrand({ ...ctxQ.data.brand }); }, [ctxQ.data]);
  const refresh = () => { ctxQ.refetch(); featuresQ.refetch(); plansQ.refetch(); proposalsQ.refetch(); structureQ.refetch(); updatesQ.refetch(); portfolioQ.refetch(); financeQ.refetch(); contractsQ.refetch(); };
  const saveSettings = api.saveSettings.useMutation({ onSuccess: () => { toast.success("Identidade comercial atualizada."); refresh(); }, onError: (e:any)=>toast.error(e.message) });
  const savePlan = api.upsertPlan.useMutation({ onSuccess: () => { toast.success("Plano salvo."); setPlanModal(null); refresh(); }, onError:(e:any)=>toast.error(e.message) });
  const saveFeature = api.upsertFeature.useMutation({ onSuccess: () => { toast.success("Funcionalidade salva."); setFeatureModal(null); refresh(); }, onError:(e:any)=>toast.error(e.message) });
  const saveProposal = api.upsertProposal.useMutation({ onSuccess: () => { toast.success("Proposta salva."); setProposalModal(null); refresh(); }, onError:(e:any)=>toast.error(e.message) });
  const generatePdf = api.generatePdf.useMutation({ onSuccess:(r:any)=>{ proposalsQ.refetch(); window.open(r.url,"_blank"); }, onError:(e:any)=>toast.error(e.message) });
  const generateAnnex = api.generateTechnicalAnnex.useMutation({ onSuccess:(r:any)=>{ proposalsQ.refetch(); window.open(r.url,"_blank"); }, onError:(e:any)=>toast.error(e.message) });
  const saveAddon = api.upsertAddon.useMutation({onSuccess:()=>{toast.success("Add-on salvo.");setAddonModal(null);refresh();},onError:(e:any)=>toast.error(e.message)});
  const saveBands = api.savePricingBands.useMutation({onSuccess:()=>{toast.success("Faixas comerciais atualizadas.");refresh();},onError:(e:any)=>toast.error(e.message)});
  const sendProposal = api.sendProposal.useMutation({ onSuccess:(r:any)=>{ toast.success(r.preview ? "Envio registrado em modo de teste." : "Proposta enviada por e-mail."); refresh(); }, onError:(e:any)=>toast.error(e.message) });
  const approve = api.approveProposal.useMutation({ onSuccess:()=>{toast.success("Proposta aprovada e financeiro programado.");refresh();},onError:(e:any)=>toast.error(e.message)});
  const updateReceivable = api.updateReceivable.useMutation({ onSuccess:()=>{toast.success("Recebimento atualizado.");refresh();},onError:(e:any)=>toast.error(e.message)});
  const publishUpdate = api.publishPlatformUpdate.useMutation({onSuccess:(result:any)=>{toast.success(`Atualização publicada em ${result.results?.length||0} rede(s).`);updatesQ.refetch();portfolioQ.refetch();},onError:(e:any)=>toast.error(e.message)});
  const generatePortfolio = api.generatePortfolio.useMutation({onSuccess:(result:any)=>{toast.success(`Portfólio gerado com ${result.featureCount} funcionalidades.`);portfolioQ.refetch();window.open(result.url,"_blank");},onError:(e:any)=>toast.error(e.message)});
  const uploadPortfolioImage = api.uploadPortfolioImage.useMutation({onSuccess:()=>{toast.success("Imagem adicionada à biblioteca do portfólio.");portfolioQ.refetch();},onError:(e:any)=>toast.error(e.message)});
  const setPrimaryPortfolioImage = api.setPrimaryPortfolioImage.useMutation({onSuccess:()=>{toast.success("Imagem padrão atualizada.");portfolioQ.refetch();},onError:(e:any)=>toast.error(e.message)});
  const deletePortfolioImage = api.deletePortfolioImage.useMutation({onSuccess:()=>{toast.success("Imagem removida.");portfolioQ.refetch();},onError:(e:any)=>toast.error(e.message)});
  const saveWhiteLabelPortfolioFeature = api.saveWhiteLabelPortfolioFeature.useMutation({onSuccess:()=>{toast.success("Disponibilidade no portfólio atualizada.");portfolioQ.refetch();},onError:(e:any)=>toast.error(e.message)});
  const createContract = api.createContractFromProposal.useMutation({onSuccess:()=>{toast.success("Contrato criado a partir da proposta.");setContractModal(null);refresh();},onError:(e:any)=>toast.error(e.message)});
  const generateContractPdf = api.generateContractPdf.useMutation({onSuccess:(r:any)=>{toast.success("PDF do contrato gerado.");refresh();window.open(r.url,"_blank");},onError:(e:any)=>toast.error(e.message)});
  const updateContractDocument = api.updateContractDocument.useMutation({onSuccess:()=>{toast.success("Contrato atualizado. Gere o PDF novamente.");setEditContractModal(null);refresh();},onError:(e:any)=>toast.error(e.message)});
  const deleteContractDocument = api.deleteContractDocument.useMutation({onSuccess:()=>{toast.success("Contrato removido da visão operacional.");setDeleteContract(null);refresh();},onError:(e:any)=>toast.error(e.message)});
  const sendContractForSignature = api.sendContractForSignature.useMutation({onSuccess:(r:any)=>{toast.success(r.preview ? "Envio para assinatura registrado em modo de teste." : "Contrato enviado para assinatura.");setSendContract(null);refresh();},onError:(e:any)=>toast.error(e.message)});
  const saveTemplate = api.upsertContractTemplate.useMutation({onSuccess:()=>{toast.success("Modelo de contrato salvo.");setTemplateModal(null);refresh();},onError:(e:any)=>toast.error(e.message)});
  const saveClause = api.upsertContractClause.useMutation({onSuccess:()=>{toast.success("Cláusula salva.");setClauseModal(null);refresh();},onError:(e:any)=>toast.error(e.message)});
  const updateContractStatus = api.updateContractStatus.useMutation({onSuccess:()=>{toast.success("Status do contrato atualizado.");refresh();},onError:(e:any)=>toast.error(e.message)});
  const uploadSigned = api.uploadSignedContract.useMutation({onSuccess:()=>{toast.success("Via assinada anexada.");setUploadContract(null);refresh();},onError:(e:any)=>toast.error(e.message)});

  const context = ctxQ.data || {};
  const features = (featuresQ.data || []) as any[];
  const plans = (plansQ.data || []) as any[];
  const proposals = (proposalsQ.data || []) as any[];
  const structure = structureQ.data || {pillars:[],addons:[],bands:[]};
  const contractData = contractsQ.data || {contracts:[],templates:[],clauses:[],proposals:[],metrics:{}};
  const tabs: Array<[Tab,string,any]> = [
    ["overview","Visão geral",BarChart3],...(context.scope?.ownerType==="global"?[["updates","Atualizações",Bell] as [Tab,string,any]]:[]),["proposals","Propostas",FileText],["contracts","Contratos",FileSignature],["portfolio","Portfólio Comercial",BriefcaseBusiness],["plans","Planos",Layers3],
    ["features","Funcionalidades",Settings2],["structure","Catálogo e preços",PackageOpen],["brand","Marca e textos",Palette],["finance","Financeiro",CreditCard],
  ];
  return <div className="max-w-7xl mx-auto p-6 space-y-5">
    <header><h1 className="text-2xl font-bold text-primary">CRM Comercial e Propostas</h1><p className="text-sm text-muted-foreground mt-1">Propostas, planos, identidade comercial e financeiro isolados neste ambiente.</p></header>
    <div className="flex gap-1 border-b overflow-x-auto">{tabs.map(([key,label,Icon])=><button key={key} onClick={()=>setTab(key)} className={`px-3 py-2 text-sm font-medium border-b-2 -mb-px whitespace-nowrap ${tab===key?"border-primary text-primary":"border-transparent text-slate-500"}`}><span className="inline-flex items-center gap-1.5"><Icon size={14}/>{label}</span></button>)}</div>

    {tab === "overview" && <div className="space-y-5">
      <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">
        <Metric label="Propostas" value={context.metrics?.proposals || 0}/><Metric label="Pipeline aberto" value={context.metrics?.open_pipeline || 0}/>
        <Metric label="Pipeline ponderado" value={brl(context.metrics?.weighted_pipeline)}/><Metric label="Follow-ups vencidos" value={context.metrics?.followups_late||0}/>
      </div>
      <div className="border-t pt-5"><h2 className="font-semibold text-lg">Ciclo comercial</h2><div className="mt-3 grid sm:grid-cols-5 gap-2">{["Proposta","Aprovação","Contrato","Cobrança","Pagamento"].map((x,i)=><div key={x} className="border rounded-md p-3 bg-white"><div className="text-xs text-muted-foreground">Etapa {i+1}</div><div className="font-semibold mt-1">{x}</div></div>)}</div></div>
    </div>}

    {tab === "updates" && <PlatformUpdatesTab data={updatesQ.data} loading={publishUpdate.isPending} onPublish={(payload:any)=>publishUpdate.mutate(payload)}/>}

    {tab === "proposals" && <section className="space-y-3">
      <div className="flex justify-between items-center"><p className="text-sm text-muted-foreground">Crie propostas com a marca, planos e preços deste ambiente.</p><Button onClick={()=>setProposalModal({})}><Plus size={14}/>Nova proposta</Button></div>
      <div className="overflow-x-auto border rounded-md bg-white"><table className="w-full text-sm"><thead className="bg-slate-50"><tr><th className="p-3 text-left">Cliente</th><th className="p-3 text-left">Plano</th><th className="p-3 text-right">Mensalidade</th><th className="p-3 text-left">Status</th><th className="p-3 text-right">Ações</th></tr></thead><tbody>{proposals.map(p=><tr key={p.id} className="border-t"><td className="p-3"><b>{p.razao_social}</b><div className="text-xs text-muted-foreground">{p.proposal_number||`#${p.id}`} · {p.responsavel || p.email || "Contato a definir"}</div><div className="text-xs text-muted-foreground">Comercial: {p.commercial_owner_name||"não definido"}</div></td><td className="p-3">{p.plan_name || "Personalizado"}</td><td className="p-3 text-right font-semibold">{brl(p.valor_mensal)}</td><td className="p-3">{statusLabel[p.status] || p.status}<div className="text-xs text-muted-foreground">{Number(p.probability_pct||0)}% · Próximo: {p.next_contact_date?new Date(p.next_contact_date).toLocaleDateString("pt-BR"):"não agendado"}</div></td><td className="p-3"><div className="flex justify-end gap-1 flex-wrap"><Button size="sm" variant="outline" onClick={()=>setProposalModal(p)}>Editar</Button><Button size="icon" variant="outline" title="Histórico e follow-up" onClick={()=>setActivityProposal(p)}><History size={14}/></Button><Button size="icon" variant="outline" title="Gerar proposta comercial" onClick={()=>generatePdf.mutate({id:Number(p.id)})}><Printer size={14}/></Button><Button size="icon" variant="outline" title="Gerar Anexo Técnico" onClick={()=>generateAnnex.mutate({id:Number(p.id)})}><FileText size={14}/></Button><Button size="icon" variant="outline" title="Revisar e enviar por e-mail" onClick={()=>setSendConfirm(p)}><Mail size={14}/></Button>{!['aprovada','convertida'].includes(p.status)&&<Button size="icon" title="Aprovar e criar financeiro" onClick={()=>approve.mutate({id:Number(p.id),createFinancialSchedule:true})}><Check size={14}/></Button>}</div></td></tr>)}</tbody></table>{!proposals.length&&<Empty text="Nenhuma proposta cadastrada."/>}</div>
    </section>}

    {tab === "contracts" && <ContractsTab data={contractData} busy={createContract.isPending||generateContractPdf.isPending||updateContractStatus.isPending||updateContractDocument.isPending||deleteContractDocument.isPending||sendContractForSignature.isPending||saveTemplate.isPending||saveClause.isPending||uploadSigned.isPending} onNew={()=>setContractModal({})} onPdf={(id:number)=>generateContractPdf.mutate({id})} onStatus={(id:number,status:string)=>status==="enviado_assinatura"?setSendContract(contractData.contracts?.find((row:any)=>Number(row.id)===Number(id))):updateContractStatus.mutate({id,status})} onUpload={setUploadContract} onEdit={setEditContractModal} onDelete={setDeleteContract} onSend={setSendContract} onEditTemplate={setTemplateModal} onEditClause={setClauseModal}/>}

    {tab === "portfolio" && <PortfolioTab data={portfolioQ.data} loading={generatePortfolio.isPending} onGenerate={(payload:any)=>generatePortfolio.mutate(payload)} onUploadImage={(payload:any)=>uploadPortfolioImage.mutate(payload)} onSetPrimary={(id:number)=>setPrimaryPortfolioImage.mutate({id})} onDeleteImage={(id:number)=>deletePortfolioImage.mutate({id})} onSaveWhiteLabelFeature={(payload:any)=>saveWhiteLabelPortfolioFeature.mutate(payload)} imageBusy={uploadPortfolioImage.isPending||setPrimaryPortfolioImage.isPending||deletePortfolioImage.isPending||saveWhiteLabelPortfolioFeature.isPending}/>}

    {tab === "plans" && <section className="space-y-4">
      <div className="flex justify-between"><p className="text-sm text-muted-foreground">Cada plano possui preço, limites, serviços e funcionalidades próprias.</p><Button onClick={()=>setPlanModal({})}><Plus size={14}/>Novo plano</Button></div>
      <div className="grid md:grid-cols-3 gap-3">{plans.map(p=><div key={p.id} className="border rounded-md bg-white p-4"><div className="flex justify-between gap-2"><h3 className="font-bold text-primary">{p.name}</h3><button className="text-sm text-primary" onClick={()=>setPlanModal(p)}>Editar</button></div><p className="text-sm text-muted-foreground min-h-10 mt-2">{p.description}</p><div className="text-2xl font-bold mt-4">{brl(p.fixed_monthly_price)}<span className="text-xs font-normal">/mês</span></div><div className="text-xs mt-2">Setup: {brl(p.setup_price)} | {p.featureIds?.length || 0} funcionalidades</div></div>)}</div>
      <PlanMatrix plans={plans} features={features}/>
    </section>}

    {tab === "features" && <section className="space-y-3"><div className="flex justify-between"><p className="text-sm text-muted-foreground">Catálogo usado nos planos e PDFs.</p><Button onClick={()=>setFeatureModal({})}><Plus size={14}/>Nova funcionalidade</Button></div>{Object.entries(groupBy(features,"category")).map(([cat,list])=><div key={cat} className="border-t pt-3"><h3 className="font-semibold text-primary">{cat}</h3><div className="grid md:grid-cols-2 gap-2 mt-2">{(list as any[]).map(f=><button key={f.id} onClick={()=>setFeatureModal(f)} className="text-left border rounded-md bg-white p-3 hover:border-primary"><b>{f.name}</b><div className="text-xs text-muted-foreground mt-1">{f.description}</div></button>)}</div></div>)}</section>}

    {tab === "structure" && <CommercialStructureTab data={structure} onEditAddon={setAddonModal} onSaveBands={(rows:any[])=>saveBands.mutate(rows)} saving={saveBands.isPending}/>}

    {tab === "brand" && brand && (
      <BrandForm value={brand} onChange={setBrand} saving={saveSettings.isPending} onSave={()=>saveSettings.mutate({brandName:brand.brand_name,legalName:brand.legal_name||undefined,logoUrl:brand.logo_url||undefined,primaryColor:brand.primary_color,secondaryColor:brand.secondary_color,presentationText:brand.presentation_text||undefined,objectiveText:brand.objective_text||undefined,contactName:brand.contact_name||undefined,contactEmail:brand.contact_email||undefined,contactPhone:brand.contact_phone||undefined,website:brand.website||undefined,commercialTerms:brand.commercial_terms||undefined,nextStepsText:brand.next_steps_text||undefined})}/>
    )}

    {tab === "finance" && (
      <FinanceTab data={financeQ.data} onPaid={(id:number)=>updateReceivable.mutate({id,status:"recebido"})}/>
    )}
    {planModal && (
      <PlanModal initial={planModal} features={features} onClose={()=>setPlanModal(null)} loading={savePlan.isPending} onSave={(d:any)=>savePlan.mutate(d)}/>
    )}
    {featureModal && (
      <FeatureModal initial={featureModal} pillars={structure.pillars as any[]} onClose={()=>setFeatureModal(null)} loading={saveFeature.isPending} onSave={(d:any)=>saveFeature.mutate(d)}/>
    )}
    {addonModal && <AddonModal initial={addonModal} onClose={()=>setAddonModal(null)} loading={saveAddon.isPending} onSave={(d:any)=>saveAddon.mutate(d)}/>}
    {contractModal && <ContractModal data={contractData} loading={createContract.isPending} onClose={()=>setContractModal(null)} onSave={(payload:any)=>createContract.mutate(payload)}/>}
    {editContractModal && <EditContractModal contract={editContractModal} loading={updateContractDocument.isPending} onClose={()=>setEditContractModal(null)} onSave={(payload:any)=>updateContractDocument.mutate(payload)}/>}
    {deleteContract && <DeleteContractModal contract={deleteContract} loading={deleteContractDocument.isPending} onClose={()=>setDeleteContract(null)} onConfirm={(payload:any)=>deleteContractDocument.mutate(payload)}/>}
    {sendContract && <SendContractModal contract={sendContract} loading={sendContractForSignature.isPending} onClose={()=>setSendContract(null)} onConfirm={(payload:any)=>sendContractForSignature.mutate(payload)}/>}
    {templateModal && <ContractTemplateModal initial={templateModal} loading={saveTemplate.isPending} onClose={()=>setTemplateModal(null)} onSave={(payload:any)=>saveTemplate.mutate(payload)}/>}
    {clauseModal && <ContractClauseModal initial={clauseModal} loading={saveClause.isPending} onClose={()=>setClauseModal(null)} onSave={(payload:any)=>saveClause.mutate(payload)}/>}
    {uploadContract && <SignedContractUploadModal contract={uploadContract} loading={uploadSigned.isPending} onClose={()=>setUploadContract(null)} onSave={(payload:any)=>uploadSigned.mutate(payload)}/>}
    {activityProposal && <ActivityModal proposal={activityProposal} onClose={()=>setActivityProposal(null)} onSaved={refresh}/>}
    {sendConfirm && <SendProposalModal proposal={sendConfirm} loading={sendProposal.isPending} onClose={()=>setSendConfirm(null)} onConfirm={()=>sendProposal.mutate({id:Number(sendConfirm.id)},{onSuccess:()=>setSendConfirm(null)})}/>}
    {proposalModal && (
      <ProposalModalV2 initial={proposalModal} brand={brand} plans={plans} features={features} addons={structure.addons as any[]} bands={structure.bands as any[]} onClose={()=>setProposalModal(null)} loading={saveProposal.isPending} onSave={(d:any)=>saveProposal.mutate(d)}/>
    )}
  </div>;
}

export default function CommercialCrm(){ return <AppLayout><CommercialWorkspace/></AppLayout>; }

function Metric({label,value}:{label:string,value:any}){return <div className="border bg-white rounded-md p-4 min-h-24"><div className="text-xs text-muted-foreground">{label}</div><div className="text-2xl font-bold text-primary mt-3">{value}</div></div>}
function Empty({text}:{text:string}){return <div className="p-10 text-center text-sm text-muted-foreground">{text}</div>}
function groupBy(rows:any[],key:string){return rows.reduce((a,r)=>{(a[r[key]] ||= []).push(r);return a},{} as Record<string,any[]>)}
function Field({label,children,wide=false}:{label:string,children:any,wide?:boolean}){return <label className={wide?"md:col-span-2":""}><span className="block text-xs font-medium mb-1">{label}</span>{children}</label>}
const area="w-full border rounded-md px-3 py-2 text-sm min-h-24";

function ContractsTab({data,busy,onNew,onPdf,onStatus,onUpload,onEdit,onDelete,onSend,onEditTemplate,onEditClause}:{data:any,busy:boolean,onNew:any,onPdf:any,onStatus:any,onUpload:any,onEdit:any,onDelete:any,onSend:any,onEditTemplate:any,onEditClause:any}){
  const contracts=(data?.contracts||[]) as any[];const templates=(data?.templates||[]) as any[];const clauses=(data?.clauses||[]) as any[];const metrics=data?.metrics||{};
  const [clauseFilter,setClauseFilter]=useState("todos");
  const filteredClauses=clauses.filter((row:any)=>clauseFilter==="todos"||row.applies_to==="todos"||row.applies_to===clauseFilter);
  const statusLabel:any={rascunho:"Rascunho",gerado:"PDF gerado",enviado_assinatura:"Enviado para assinatura",assinado:"Assinado",ativo:"Ativo",cancelado:"Cancelado",substituido:"Substituído",distratado:"Distratado"};
  return <section className="space-y-5">
    <div className="grid sm:grid-cols-4 gap-3"><Metric label="Contratos" value={metrics.total||0}/><Metric label="Em elaboração/assinatura" value={metrics.open_count||0}/><Metric label="Assinados" value={metrics.signed_count||0}/><Metric label="Renovação próxima" value={metrics.renewal_attention||0}/></div>
    <div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-lg font-semibold">Contratos comerciais</h2><p className="text-sm text-muted-foreground">Gere contratos por proposta ou contrato direto White Label, com versão, assinatura, histórico e biblioteca de cláusulas por aplicação.</p></div><Button onClick={onNew}><Plus size={14}/>Novo contrato</Button></div>
    <div className="overflow-x-auto border rounded-md bg-white"><table className="w-full text-sm"><thead className="bg-slate-50"><tr><th className="p-3 text-left">Contrato</th><th className="p-3 text-left">Cliente</th><th className="p-3">Vigência</th><th className="p-3">Status</th><th className="p-3 text-right">Ações</th></tr></thead><tbody>{contracts.map(row=><tr className="border-t" key={row.id}><td className="p-3"><b>{row.contract_number||`#${row.id}`}</b><div className="text-xs text-muted-foreground">{row.title} · {row.contract_type} · versão {row.version||1}</div></td><td className="p-3">{row.client_name}<div className="text-xs text-muted-foreground">{row.cnpj||row.proposal_number||"Contrato direto"}</div></td><td className="p-3 text-center text-xs">{row.valid_from?new Date(row.valid_from).toLocaleDateString("pt-BR"):"-"}<br/>{row.valid_until?new Date(row.valid_until).toLocaleDateString("pt-BR"):"-"}</td><td className="p-3 text-center"><span className="rounded-sm bg-slate-100 px-2 py-1 text-xs">{statusLabel[row.status]||row.status}</span><div className="mt-1 text-xs text-muted-foreground">{row.signature_status}{row.last_sent_to?` · ${row.last_sent_to}`:""}</div></td><td className="p-3"><div className="flex justify-end gap-1 flex-wrap"><Button size="icon" variant="outline" title="Editar contrato" disabled={busy||["assinado","ativo","distratado"].includes(row.status)} onClick={()=>onEdit(row)}><Pencil size={14}/></Button><Button size="icon" variant="outline" title="Gerar PDF" disabled={busy} onClick={()=>onPdf(Number(row.id))}><Printer size={14}/></Button>{row.pdf_url?<a href={row.pdf_url} target="_blank" rel="noreferrer"><Button size="sm" variant="outline">PDF</Button></a>:null}<Button size="icon" variant="outline" title="Enviar para assinatura" disabled={busy} onClick={()=>onSend(row)}><Send size={14}/></Button><Button size="icon" variant="outline" title="Anexar via assinada" onClick={()=>onUpload(row)}><Upload size={14}/></Button>{row.signed_pdf_url?<a href={row.signed_pdf_url} target="_blank" rel="noreferrer"><Button size="sm" variant="outline">Assinado</Button></a>:null}<select className="border rounded px-2 text-xs" value={row.status} disabled={busy} onChange={e=>onStatus(Number(row.id),e.target.value)}>{Object.entries(statusLabel).filter(([value])=>value!=="enviado_assinatura").map(([value,label]:any)=><option key={value} value={value}>{label}</option>)}</select><Button size="icon" variant="outline" title="Excluir contrato" disabled={busy} onClick={()=>onDelete(row)}><Trash2 size={14}/></Button></div></td></tr>)}</tbody></table>{!contracts.length&&<Empty text="Nenhum contrato gerado neste ambiente."/>}</div>
    <div className="grid gap-4 lg:grid-cols-2">
      <div className="border bg-white p-4"><div className="flex justify-between items-center"><h3 className="font-semibold">Modelos de contrato</h3><Button size="sm" variant="outline" onClick={()=>onEditTemplate({})}><Plus size={13}/>Modelo</Button></div><div className="mt-3 space-y-2">{templates.map(row=><button key={row.id} className="block w-full border p-3 text-left hover:border-primary" onClick={()=>onEditTemplate(row)}><b className="text-sm">{row.name}</b><small className="block text-muted-foreground">{row.contract_type} · {row.legal_review_status}</small></button>)}{!templates.length?<Empty text="Nenhum modelo cadastrado."/>:null}</div></div>
      <div className="border bg-white p-4"><div className="flex justify-between items-center gap-3"><h3 className="font-semibold">Biblioteca de cláusulas</h3><Button size="sm" variant="outline" onClick={()=>onEditClause({})}><Plus size={13}/>Cláusula</Button></div><div className="mt-3 flex items-center gap-2 text-xs"><span className="text-muted-foreground">Aplicação</span><select className="border rounded px-2 py-1" value={clauseFilter} onChange={e=>setClauseFilter(e.target.value)}><option value="todos">Todos</option><option value="saas">SaaS</option><option value="white_label">White Label</option><option value="aditivo">Aditivo</option><option value="distrato">Distrato</option></select></div><div className="mt-3 max-h-96 space-y-2 overflow-y-auto">{filteredClauses.map(row=><button key={row.id} className="block w-full border p-3 text-left hover:border-primary" onClick={()=>onEditClause(row)}><b className="text-sm">{row.title}</b><small className="block text-muted-foreground">{row.category} · {row.applies_to} · {row.legal_review_status}</small></button>)}{!filteredClauses.length?<Empty text="Nenhuma cláusula para esta aplicação."/>:null}</div></div>
    </div>
  </section>;
}

function ContractModal({data,onClose,onSave,loading}:{data:any,onClose:any,onSave:any,loading:boolean}){
  const proposals=(data?.proposals||[]) as any[];const templates=(data?.templates||[]) as any[];const clauses=(data?.clauses||[]) as any[];
  const firstProposal=proposals[0];const [f,setF]=useState({proposalId:firstProposal?Number(firstProposal.id):0,templateId:0,contractType:"saas",title:"",clientName:"",cnpj:"",contactName:"",contactEmail:"",planName:"",monthlyValue:0,setupValue:0,featuresSummary:"",validFrom:new Date().toISOString().slice(0,10),validUntil:"",renewalAlertDays:60,clauseIds:[] as number[]});
  const set=(k:string,v:any)=>setF({...f,[k]:v});
  const compatibleTemplates=templates.filter((t:any)=>Boolean(t.is_active)&&t.contract_type===f.contractType);
  const compatibleClauses=clauses.filter((c:any)=>c.is_active&&(c.applies_to==="todos"||c.applies_to===f.contractType));
  useEffect(()=>{if(!compatibleTemplates.some((t:any)=>Number(t.id)===Number(f.templateId)))setF(row=>({...row,templateId:compatibleTemplates[0]?Number(compatibleTemplates[0].id):0,clauseIds:compatibleClauses.map((c:any)=>Number(c.id))}))},[f.contractType,templates.length,clauses.length]);
  const selectedProposal=proposals.find((p:any)=>Number(p.id)===Number(f.proposalId));
  const direct=!f.proposalId;
  return <Modal title="Novo contrato" onClose={onClose}><div className="grid md:grid-cols-2 gap-3">
    <Field label="Tipo"><select className="w-full border rounded-md px-3 py-2" value={f.contractType} onChange={e=>setF({...f,contractType:e.target.value,templateId:0,clauseIds:[]})}><option value="saas">SaaS</option><option value="white_label">White Label</option><option value="prestador">Prestador / Clínica</option><option value="aditivo">Aditivo</option><option value="distrato">Distrato</option></select></Field>
    <Field label="Modelo"><select className="w-full border rounded-md px-3 py-2" value={f.templateId} onChange={e=>set("templateId",Number(e.target.value))}><option value={0}>Selecione</option>{compatibleTemplates.map((t:any)=><option key={t.id} value={t.id}>{t.name}</option>)}</select></Field>
    <Field label="Proposta de origem" wide><select className="w-full border rounded-md px-3 py-2" value={f.proposalId} onChange={e=>set("proposalId",Number(e.target.value))}><option value={0}>Contrato direto sem proposta</option>{proposals.map(p=><option key={p.id} value={p.id}>{p.proposal_number||`#${p.id}`} · {p.razao_social} · {p.plan_name||"sem plano"}</option>)}</select>{selectedProposal?<p className="mt-1 text-xs text-muted-foreground">Cliente e valores serão preenchidos com os dados da proposta selecionada.</p>:<p className="mt-1 text-xs text-muted-foreground">Use contrato direto para White Label, aditivo, distrato ou formalizações sem proposta comum.</p>}</Field>
    {direct&&<><Field label="Cliente / Rede"><Input value={f.clientName} onChange={e=>set("clientName",e.target.value)}/></Field><Field label="CNPJ"><Input value={f.cnpj} onChange={e=>set("cnpj",e.target.value)}/></Field><Field label="Responsável"><Input value={f.contactName} onChange={e=>set("contactName",e.target.value)}/></Field><Field label="E-mail para assinatura"><Input value={f.contactEmail} onChange={e=>set("contactEmail",e.target.value)}/></Field><Field label="Plano / escopo"><Input value={f.planName} onChange={e=>set("planName",e.target.value)} placeholder={f.contractType==="white_label"?"White Label":"Escopo comercial"}/></Field><Field label="Mensalidade"><Input type="number" value={f.monthlyValue} onChange={e=>set("monthlyValue",Number(e.target.value))}/></Field><Field label="Setup"><Input type="number" value={f.setupValue} onChange={e=>set("setupValue",Number(e.target.value))}/></Field><Field label="Resumo do escopo" wide><textarea className={area} value={f.featuresSummary} onChange={e=>set("featuresSummary",e.target.value)} placeholder="Descreva módulos, limites, serviços e condições específicas deste contrato direto."/></Field></>}
    <Field label="Título" wide><Input value={f.title} onChange={e=>set("title",e.target.value)} placeholder="Opcional. Ex.: Contrato SaaS - Cliente X"/></Field>
    <Field label="Vigência inicial"><Input type="date" value={f.validFrom} onChange={e=>set("validFrom",e.target.value)}/></Field><Field label="Vigência final"><Input type="date" value={f.validUntil} onChange={e=>set("validUntil",e.target.value)}/></Field>
    <Field label="Alerta de renovação (dias)"><Input type="number" value={f.renewalAlertDays} onChange={e=>set("renewalAlertDays",Number(e.target.value))}/></Field>
    <Field label="Cláusulas aplicadas" wide><div className="max-h-64 space-y-1 overflow-y-auto border p-3">{compatibleClauses.map((c:any)=><label key={c.id} className="flex gap-2 text-sm"><input type="checkbox" checked={f.clauseIds.includes(Number(c.id))} onChange={e=>set("clauseIds",e.target.checked?[...f.clauseIds,Number(c.id)]:f.clauseIds.filter(id=>id!==Number(c.id)))}/><span><b>{c.title}</b><small className="block text-muted-foreground">{c.applies_to} · {c.legal_review_status}</small></span></label>)}</div></Field>
  </div><div className="mt-4 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={loading||!f.templateId||(!f.proposalId&&!f.clientName)} onClick={()=>onSave({...f,proposalId:f.proposalId||null,validFrom:f.validFrom||null,validUntil:f.validUntil||null,title:f.title||undefined,contactEmail:f.contactEmail||undefined,clientName:f.clientName||undefined,cnpj:f.cnpj||undefined,contactName:f.contactName||undefined,planName:f.planName||undefined,featuresSummary:f.featuresSummary||undefined})}>{loading?<Loader2 size={14} className="animate-spin"/>:<FileSignature size={14}/>}Criar contrato</Button></div></Modal>;
}

function EditContractModal({contract,onClose,onSave,loading}:{contract:any,onClose:any,onSave:any,loading:boolean}){
  const [f,setF]=useState({id:Number(contract.id),title:contract.title||"",clientName:contract.client_name||"",cnpj:contract.cnpj||"",validFrom:contract.valid_from?String(contract.valid_from).slice(0,10):"",validUntil:contract.valid_until?String(contract.valid_until).slice(0,10):"",renewalAlertDays:Number(contract.renewal_alert_days||60),contentHtml:contract.content_html||""});
  const set=(k:string,v:any)=>setF({...f,[k]:v});
  return <Modal title="Editar contrato" onClose={onClose}><div className="space-y-3"><div className="border-l-4 border-amber-500 bg-amber-50 p-4 text-sm text-amber-950"><b>A edição cria nova versão operacional.</b><p className="mt-1">Depois de salvar, gere novamente o PDF. Contratos assinados ou ativos devem ser tratados por aditivo/distrato.</p></div><div className="grid md:grid-cols-2 gap-3"><Field label="Título"><Input value={f.title} onChange={e=>set("title",e.target.value)}/></Field><Field label="Cliente"><Input value={f.clientName} onChange={e=>set("clientName",e.target.value)}/></Field><Field label="CNPJ"><Input value={f.cnpj} onChange={e=>set("cnpj",e.target.value)}/></Field><Field label="Alerta renovação (dias)"><Input type="number" value={f.renewalAlertDays} onChange={e=>set("renewalAlertDays",Number(e.target.value))}/></Field><Field label="Vigência inicial"><Input type="date" value={f.validFrom} onChange={e=>set("validFrom",e.target.value)}/></Field><Field label="Vigência final"><Input type="date" value={f.validUntil} onChange={e=>set("validUntil",e.target.value)}/></Field><Field label="Conteúdo HTML do contrato" wide><textarea className="w-full border rounded-md px-3 py-2 text-sm min-h-96 font-mono" value={f.contentHtml} onChange={e=>set("contentHtml",e.target.value)}/></Field></div></div><div className="mt-4 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={loading||!f.title||!f.clientName||!f.contentHtml} onClick={()=>onSave({...f,cnpj:f.cnpj||undefined,validFrom:f.validFrom||null,validUntil:f.validUntil||null})}>{loading?<Loader2 size={14} className="animate-spin"/>:<Save size={14}/>}Salvar edição</Button></div></Modal>
}

function DeleteContractModal({contract,onClose,onConfirm,loading}:{contract:any,onClose:any,onConfirm:any,loading:boolean}){
  const [reason,setReason]=useState("");
  const used=Boolean(contract.pdf_url||contract.signed_pdf_url||contract.last_sent_at||["enviado_assinatura","assinado","ativo","distratado"].includes(contract.status));
  return <Modal title="Excluir contrato" onClose={onClose}><div className="space-y-4"><div className="border-l-4 border-red-600 bg-red-50 p-4 text-sm text-red-950"><b>{used?"Este contrato possui uso ou evidência vinculada.":"Contrato ainda sem uso formal identificado."}</b><p className="mt-1">A plataforma removerá da visão operacional e manterá o histórico/auditoria para rastreabilidade.</p></div><dl className="grid grid-cols-[110px_1fr] gap-y-2 text-sm"><dt className="text-muted-foreground">Contrato</dt><dd>{contract.contract_number||`#${contract.id}`}</dd><dt className="text-muted-foreground">Cliente</dt><dd>{contract.client_name}</dd></dl><Field label="Motivo"><textarea className={area} value={reason} onChange={e=>setReason(e.target.value)} placeholder="Opcional, mas recomendado para auditoria."/></Field></div><div className="mt-4 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button variant="destructive" disabled={loading} onClick={()=>onConfirm({id:Number(contract.id),reason:reason||undefined})}>{loading?<Loader2 size={14} className="animate-spin"/>:<Trash2 size={14}/>}Excluir</Button></div></Modal>
}

function SendContractModal({contract,onClose,onConfirm,loading}:{contract:any,onClose:any,onConfirm:any,loading:boolean}){
  const [recipientEmail,setRecipientEmail]=useState(contract.last_sent_to||"");
  const [message,setMessage]=useState("Segue contrato disponibilizado para assinatura. Revise o documento e formalize a assinatura conforme orientações.");
  const [sendEmail,setSendEmail]=useState(true);
  return <Modal title="Confirmar envio para assinatura" onClose={onClose}><div className="space-y-4"><div className="border-l-4 border-amber-500 bg-amber-50 p-4 text-sm text-amber-950"><b>Este contrato será enviado/registrado para assinatura.</b><p className="mt-1">Confirme destinatário e mensagem antes de continuar. O histórico registrará data, usuário, destinatário e status.</p></div><dl className="grid grid-cols-[110px_1fr] gap-y-2 text-sm"><dt className="text-muted-foreground">Contrato</dt><dd>{contract.contract_number||`#${contract.id}`}</dd><dt className="text-muted-foreground">Cliente</dt><dd>{contract.client_name}</dd></dl><Field label="E-mail destinatário"><Input value={recipientEmail} onChange={e=>setRecipientEmail(e.target.value)} placeholder="email@cliente.com"/></Field><Field label="Mensagem"><textarea className={area} value={message} onChange={e=>setMessage(e.target.value)}/></Field><label className="flex gap-2 text-sm"><input type="checkbox" checked={sendEmail} onChange={e=>setSendEmail(e.target.checked)}/>Enviar e-mail automaticamente agora</label></div><div className="mt-4 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={loading||!recipientEmail} onClick={()=>onConfirm({id:Number(contract.id),recipientEmail,message:message||undefined,sendEmail})}>{loading?<Loader2 size={14} className="animate-spin"/>:<Send size={14}/>}Confirmar</Button></div></Modal>
}

function ContractTemplateModal({initial,onClose,onSave,loading}:{initial:any,onClose:any,onSave:any,loading:boolean}){const [f,setF]=useState({id:initial.id,code:initial.code||"",name:initial.name||"",contractType:initial.contract_type||"saas",description:initial.description||"",baseText:initial.base_text||"",isActive:initial.id?Boolean(initial.is_active):true,legalReviewStatus:initial.legal_review_status||"pendente_juridico"});const set=(k:string,v:any)=>setF({...f,[k]:v});return <Modal title={initial.id?"Editar modelo":"Novo modelo de contrato"} onClose={onClose}><div className="grid md:grid-cols-2 gap-3"><Field label="Código"><Input value={f.code} onChange={e=>set("code",e.target.value)}/></Field><Field label="Nome"><Input value={f.name} onChange={e=>set("name",e.target.value)}/></Field><Field label="Tipo"><select className="w-full border rounded-md px-3 py-2" value={f.contractType} onChange={e=>set("contractType",e.target.value)}><option value="saas">SaaS</option><option value="white_label">White Label</option><option value="prestador">Prestador / Clínica</option><option value="aditivo">Aditivo</option><option value="distrato">Distrato</option></select></Field><Field label="Status jurídico"><select className="w-full border rounded-md px-3 py-2" value={f.legalReviewStatus} onChange={e=>set("legalReviewStatus",e.target.value)}><option value="pendente_juridico">Pendente jurídico</option><option value="aprovado">Aprovado</option><option value="revisar">Revisar</option></select></Field><Field label="Descrição" wide><Input value={f.description} onChange={e=>set("description",e.target.value)}/></Field><Field label="Texto base" wide><textarea className="w-full border rounded-md px-3 py-2 text-sm min-h-80 font-mono" value={f.baseText} onChange={e=>set("baseText",e.target.value)} placeholder="{{CLIENT_NAME}}, {{CLAUSES}}, {{MONTHLY_VALUE}}..."/></Field><label className="flex gap-2 text-sm"><input type="checkbox" checked={f.isActive} onChange={e=>set("isActive",e.target.checked)}/>Ativo</label></div><div className="mt-4 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={loading||!f.code||!f.name||!f.baseText} onClick={()=>onSave(f)}><Save size={14}/>Salvar</Button></div></Modal>}

function ContractClauseModal({initial,onClose,onSave,loading}:{initial:any,onClose:any,onSave:any,loading:boolean}){const [f,setF]=useState({id:initial.id,code:initial.code||"",title:initial.title||"",category:initial.category||"",appliesTo:initial.applies_to||"todos",clauseText:initial.clause_text||"",isActive:initial.id?Boolean(initial.is_active):true,requiresLegalReview:initial.id?Boolean(initial.requires_legal_review):true,legalReviewStatus:initial.legal_review_status||"pendente_juridico",sortOrder:Number(initial.sort_order||0)});const set=(k:string,v:any)=>setF({...f,[k]:v});return <Modal title={initial.id?"Editar cláusula":"Nova cláusula"} onClose={onClose}><div className="grid md:grid-cols-2 gap-3"><Field label="Código"><Input value={f.code} onChange={e=>set("code",e.target.value)}/></Field><Field label="Título"><Input value={f.title} onChange={e=>set("title",e.target.value)}/></Field><Field label="Categoria"><Input value={f.category} onChange={e=>set("category",e.target.value)}/></Field><Field label="Aplicação"><select className="w-full border rounded-md px-3 py-2" value={f.appliesTo} onChange={e=>set("appliesTo",e.target.value)}><option value="todos">Todos</option><option value="saas">SaaS</option><option value="white_label">White Label</option><option value="prestador">Prestador / Clínica</option><option value="aditivo">Aditivo</option><option value="distrato">Distrato</option></select></Field><Field label="Status jurídico"><select className="w-full border rounded-md px-3 py-2" value={f.legalReviewStatus} onChange={e=>set("legalReviewStatus",e.target.value)}><option value="pendente_juridico">Pendente jurídico</option><option value="aprovado">Aprovado</option><option value="revisar">Revisar</option></select></Field><Field label="Ordem"><Input type="number" value={f.sortOrder} onChange={e=>set("sortOrder",Number(e.target.value))}/></Field><Field label="Texto da cláusula" wide><textarea className="w-full border rounded-md px-3 py-2 text-sm min-h-64" value={f.clauseText} onChange={e=>set("clauseText",e.target.value)}/></Field><label className="flex gap-2 text-sm"><input type="checkbox" checked={f.isActive} onChange={e=>set("isActive",e.target.checked)}/>Ativa</label><label className="flex gap-2 text-sm"><input type="checkbox" checked={f.requiresLegalReview} onChange={e=>set("requiresLegalReview",e.target.checked)}/>Exige revisão jurídica</label></div><div className="mt-4 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={loading||!f.code||!f.title||!f.clauseText} onClick={()=>onSave(f)}><Save size={14}/>Salvar</Button></div></Modal>}

function SignedContractUploadModal({contract,onClose,onSave,loading}:{contract:any,onClose:any,onSave:any,loading:boolean}){const [fileName,setFileName]=useState("");const [fileBase64,setFileBase64]=useState("");const pick=(file?:File|null)=>{if(!file)return;setFileName(file.name);const reader=new FileReader();reader.onload=()=>setFileBase64(String(reader.result||""));reader.readAsDataURL(file);};return <Modal title="Anexar contrato assinado" onClose={onClose}><div className="space-y-4"><div className="border-l-4 border-primary bg-slate-50 p-4 text-sm"><b>{contract.contract_number||`#${contract.id}`}</b><p className="mt-1 text-muted-foreground">A via assinada será vinculada ao contrato e o status passará para assinado.</p></div><Input type="file" accept="application/pdf,image/*" onChange={e=>pick(e.target.files?.[0])}/>{fileName?<p className="text-sm text-muted-foreground">Arquivo selecionado: {fileName}</p>:null}</div><div className="mt-4 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={loading||!fileBase64} onClick={()=>onSave({id:Number(contract.id),fileBase64,fileName:fileName||"contrato_assinado.pdf"})}>{loading?<Loader2 size={14} className="animate-spin"/>:<Upload size={14}/>}Anexar assinado</Button></div></Modal>}

function PlatformUpdatesTab({data,onPublish,loading}:{data:any,onPublish:any,loading:boolean}){
  const updates=(data?.updates||[]) as any[];const partners=(data?.partners||[]) as any[];
  const [selectedUpdate,setSelectedUpdate]=useState<number>(0);const [partnerIds,setPartnerIds]=useState<number[]>([]);const [featureCodes,setFeatureCodes]=useState<string[]>([]);
  const update=updates.find(row=>Number(row.id)===Number(selectedUpdate))||updates[0];
  const availableCodes=useMemo(()=>{try{return JSON.parse(update?.feature_codes_json||"[]") as string[]}catch{return []}},[update?.feature_codes_json]);
  useEffect(()=>{if(!selectedUpdate&&updates[0])setSelectedUpdate(Number(updates[0].id));},[updates,selectedUpdate]);
  useEffect(()=>{if(update){try{setFeatureCodes(JSON.parse(update.feature_codes_json||"[]"))}catch{setFeatureCodes([])}}},[update?.id]);
  const toggle=(id:number,checked:boolean)=>setPartnerIds(rows=>checked?[...new Set([...rows,id])]:rows.filter(value=>value!==id));
  return <section className="space-y-5"><div className="border-l-4 border-cyan-600 bg-cyan-50 p-4"><h2 className="font-semibold text-cyan-950">Atualizações da Plataforma</h2><p className="mt-1 text-sm text-cyan-900">Os artigos do Manual são publicados automaticamente. Catálogo, matriz e portfólio são enviados somente às redes selecionadas.</p></div>{!updates.length?<Empty text="Nenhum pacote de atualização disponível."/>:<><div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_360px]"><div className="border bg-white p-4"><label className="text-xs font-semibold">Pacote de atualização</label><select className="mt-1 w-full border px-3 py-2" value={update?.id||""} onChange={event=>setSelectedUpdate(Number(event.target.value))}>{updates.map(row=><option key={row.id} value={row.id}>{row.title}</option>)}</select>{update&&<div className="mt-4"><h3 className="text-lg font-semibold text-primary">{update.title}</h3><p className="mt-1 text-sm text-muted-foreground">{update.summary}</p><div className="mt-4 grid grid-cols-3 gap-px bg-slate-200"><Metric label="Funcionalidades" value={availableCodes.length}/><Metric label="Manuais automáticos" value={Number(update.manuals_created||0)+Number(update.manuals_updated||0)}/><Metric label="Redes publicadas" value={update.published_partners||0}/></div><h4 className="mt-5 text-sm font-semibold">Conteúdos comerciais deste pacote</h4><div className="mt-2 grid sm:grid-cols-2 gap-2">{availableCodes.map(code=><label key={code} className="flex items-center gap-2 border px-3 py-2 text-sm"><input type="checkbox" checked={featureCodes.includes(code)} onChange={event=>setFeatureCodes(rows=>event.target.checked?[...new Set([...rows,code])]:rows.filter(value=>value!==code))}/>{code.replace(/_/g," ")}</label>)}</div></div>}</div><div className="border bg-white p-4"><h3 className="font-semibold">White Labels destinatários</h3><p className="mt-1 text-xs text-muted-foreground">Somente as redes marcadas recebem a atualização comercial.</p><div className="mt-3 max-h-80 space-y-2 overflow-y-auto">{partners.map(partner=><label key={partner.id} className="flex items-center justify-between gap-3 border p-3 text-sm"><span><b>{partner.name}</b><small className="block text-muted-foreground">{partner.published_updates||0} pacote(s) recebido(s)</small></span><input type="checkbox" checked={partnerIds.includes(Number(partner.id))} onChange={event=>toggle(Number(partner.id),event.target.checked)}/></label>)}</div><Button className="mt-4 w-full" disabled={loading||!update||!partnerIds.length||!featureCodes.length} onClick={()=>onPublish({updateId:Number(update.id),partnerIds,featureCodes})}>{loading?<Loader2 size={14} className="animate-spin"/>:<Bell size={14}/>}Enviar atualizações</Button></div></div></>}</section>;
}

function PortfolioTab({data,onGenerate,loading,onUploadImage,onSetPrimary,onDeleteImage,onSaveWhiteLabelFeature,imageBusy}:{data:any,onGenerate:any,loading:boolean,onUploadImage:any,onSetPrimary:any,onDeleteImage:any,onSaveWhiteLabelFeature:any,imageBusy:boolean}){
  const pillars=(data?.pillars||[]) as any[];const allFeatures=(data?.features||[]) as any[];const runs=(data?.runs||[]) as any[];const isWhiteLabel=data?.ownerType==="white_label";
  const features=isWhiteLabel?allFeatures.filter(feature=>Boolean(feature.wl_enabled)&&Boolean(feature.show_in_portfolio)):allFeatures;
  const [mode,setMode]=useState<"complete"|"pillar"|"custom"|"profile">("complete");
  const [pillarCodes,setPillarCodes]=useState<string[]>([]);const [featureCodes,setFeatureCodes]=useState<string[]>([]);const [audienceProfile,setAudienceProfile]=useState<"diretoria"|"rh"|"sesmt"|"medico"|"engenharia"|"colaborador"|"qualidade">("diretoria");
  const [title,setTitle]=useState("Ecossistema Integrado de Saúde e Segurança do Trabalho");const [presentationText,setPresentationText]=useState("");const [consultantName,setConsultantName]=useState("");const [consultantContact,setConsultantContact]=useState("");const [search,setSearch]=useState("");
  const toggle=(rows:string[],setRows:any,value:string,checked:boolean)=>setRows(checked?[...new Set([...rows,value])]:rows.filter(item=>item!==value));
  const profileTerms:Record<string,string[]>={diretoria:["diretoria","gestor","indicador","analytics","dashboard","conformidade"],rh:["rh","pessoas","colaborador","dossiê","treinamento","pcd","afastamento","cipa"],sesmt:["sesmt","pgr","gro","gse","epi","risco","esocial","segurança"],medico:["médico","medico","pcmso","exame","aso","cat","pca","vacinação","saúde ocupacional"],engenharia:["engenharia","pgr","gse","ltcat","insalubridade","periculosidade","ergonomia"],colaborador:["colaborador","portal","meus","minhas","dossiê","curso","certificado","requisição","aso","epi","dds","vacina","campanha","suporte"],qualidade:["qualidade","sgq","iso","auditoria","processo","não conformidade","fornecedor","indicador","competência"]};
  const matchesProfile=(feature:any)=>{const text=[feature.name,feature.category,feature.module_name,feature.description,feature.audience_json].join(" ").toLowerCase();return profileTerms[audienceProfile].some(term=>text.includes(term));};
  const selectedFeatures=mode==="complete"?features:mode==="profile"?features.filter(matchesProfile):mode==="pillar"?features.filter(f=>pillarCodes.includes(String(f.pillar_code))):features.filter(f=>featureCodes.includes(String(f.code))||pillarCodes.includes(String(f.pillar_code)));
  const filteredFeatures=features.filter(feature=>`${feature.name} ${feature.category} ${feature.code}`.toLowerCase().includes(search.toLowerCase()));
  const payload={mode,title,pillarCodes,featureCodes,audienceProfile:mode==="profile"?audienceProfile:undefined,presentationText:presentationText||undefined,consultantName:consultantName||undefined,consultantContact:consultantContact||undefined};
  return <section className="space-y-5">
    <div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-lg font-semibold">Portfólio Comercial Vivo</h2><p className="text-sm text-muted-foreground">Base global versionada, seleção por jornada e apresentação comercial com identidade deste ambiente.</p></div><div className="text-xs text-muted-foreground">Base {data?.releaseCode||"atual"} · {allFeatures.length} disponíveis</div></div>
    {isWhiteLabel&&<details className="border bg-white p-4"><summary className="cursor-pointer font-semibold">Configurar catálogo desta White Label</summary><p className="mt-1 text-xs text-muted-foreground">A Base Global permanece única. Aqui a rede escolhe apenas o que deseja habilitar e apresentar.</p><div className="mt-3 max-h-96 overflow-y-auto border">{allFeatures.map(feature=><div key={feature.id} className="flex items-center justify-between gap-3 border-b p-3 text-sm"><div><b>{feature.name}</b><small className="block text-muted-foreground">{feature.category} · v{feature.content_version||"1.0"}</small></div><div className="flex items-center gap-3"><label className="flex items-center gap-1"><input type="checkbox" checked={Boolean(feature.wl_enabled)} onChange={event=>onSaveWhiteLabelFeature({featureId:Number(feature.id),enabled:event.target.checked,showInPortfolio:event.target.checked?Boolean(feature.show_in_portfolio):false,sortOrder:Number(feature.portfolio_sort_order||feature.sort_order||0)})}/>Habilitada</label><label className="flex items-center gap-1"><input type="checkbox" disabled={!feature.wl_enabled} checked={Boolean(feature.show_in_portfolio)} onChange={event=>onSaveWhiteLabelFeature({featureId:Number(feature.id),enabled:Boolean(feature.wl_enabled),showInPortfolio:event.target.checked,sortOrder:Number(feature.portfolio_sort_order||feature.sort_order||0)})}/>Exibir</label></div></div>)}</div></details>}
    <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_390px]">
      <div className="space-y-5 border bg-white p-5">
        <div className="flex flex-wrap border p-1">{[["complete","Completo"],["pillar","Por pilar"],["profile","Por perfil"],["custom","Personalizado"]].map(([value,label])=><button key={value} className={`px-3 py-2 text-sm ${mode===value?"bg-primary text-white":""}`} onClick={()=>setMode(value as any)}>{label}</button>)}</div>
        <div className="grid gap-3 sm:grid-cols-2"><Field label="Título" wide><Input value={title} onChange={event=>setTitle(event.target.value)}/></Field><Field label="Texto de abertura" wide><textarea className={area} value={presentationText} onChange={event=>setPresentationText(event.target.value)} placeholder="Saúde, Segurança, Pessoas, Conformidade e Inteligência conectadas."/></Field><Field label="Consultor/vendedor"><Input value={consultantName} onChange={event=>setConsultantName(event.target.value)}/></Field><Field label="Contato comercial"><Input value={consultantContact} onChange={event=>setConsultantContact(event.target.value)}/></Field></div>
        {mode==="profile"&&<Field label="Público do material"><select className="w-full border rounded-md px-3 py-2" value={audienceProfile} onChange={event=>setAudienceProfile(event.target.value as any)}><option value="diretoria">Diretoria</option><option value="rh">RH</option><option value="sesmt">SESMT</option><option value="medico">Médico do Trabalho</option><option value="engenharia">Engenharia e Segurança</option><option value="colaborador">Colaborador</option><option value="qualidade">Qualidade / SGQ</option></select></Field>}
        {(mode==="pillar"||mode==="custom")&&<div><h3 className="text-sm font-semibold">Selecionar pilares</h3><div className="mt-2 grid sm:grid-cols-2 gap-2">{pillars.map(pillar=><label key={pillar.code} className="flex gap-2 border p-3 text-sm"><input type="checkbox" checked={pillarCodes.includes(String(pillar.code))} onChange={event=>toggle(pillarCodes,setPillarCodes,String(pillar.code),event.target.checked)}/><span><b>{pillar.name}</b><small className="block text-muted-foreground">{features.filter(f=>String(f.pillar_code)===String(pillar.code)).length} item(ns)</small></span></label>)}</div></div>}
        {mode==="custom"&&<div className="border p-3"><div className="flex items-center justify-between gap-3"><h3 className="text-sm font-semibold">Funcionalidades individuais</h3><Input className="max-w-64" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Buscar funcionalidade"/></div><div className="mt-3 grid max-h-80 gap-2 overflow-y-auto sm:grid-cols-2">{filteredFeatures.map(feature=><label key={feature.code} className="flex gap-2 border px-3 py-2 text-sm"><input type="checkbox" checked={featureCodes.includes(String(feature.code))} onChange={event=>toggle(featureCodes,setFeatureCodes,String(feature.code),event.target.checked)}/><span>{feature.portfolio_title||feature.name}</span></label>)}</div></div>}
        <div className="flex items-center justify-between border-t pt-4"><span className="text-sm"><b>{selectedFeatures.length}</b> funcionalidade(s) no material</span><Button disabled={loading||!title||!selectedFeatures.length} onClick={()=>onGenerate(payload)}>{loading?<Loader2 size={14} className="animate-spin"/>:<Printer size={14}/>}Gerar portfólio</Button></div>
      </div>
      <div className="space-y-4"><div className="overflow-hidden border bg-white"><div className="min-h-80 bg-primary p-7 text-white"><div className="text-xs font-semibold uppercase text-cyan-300">Prévia da abertura</div><h3 className="mt-16 text-3xl font-bold leading-tight">Sua operação de SST, conectada de ponta a ponta.</h3><p className="mt-4 text-sm text-slate-200">Saúde, Segurança, Pessoas, Conformidade e Inteligência em uma única plataforma.</p><div className="mt-8 border-t border-cyan-400 pt-3 text-xs">{selectedFeatures.length} funcionalidades · {mode==="profile"?`Perfil ${audienceProfile}`:mode}</div></div></div><div className="border bg-white p-4"><h3 className="font-semibold">Materiais recentes</h3><div className="mt-3 max-h-80 space-y-2 overflow-y-auto">{runs.map(run=><a key={run.id} className="block border p-3 hover:border-primary" href={run.pdf_url} target="_blank" rel="noreferrer"><b className="text-sm">{run.title}</b><small className="mt-1 block text-muted-foreground">{run.mode} {run.audience_profile?`· ${run.audience_profile}`:""} · {new Date(run.generated_at).toLocaleString("pt-BR")}</small></a>)}{!runs.length&&<p className="py-8 text-center text-sm text-muted-foreground">Nenhum portfólio gerado.</p>}</div></div></div>
    </div>
    <PortfolioImageLibrary features={allFeatures} images={data?.images||[]} busy={imageBusy} onUpload={onUploadImage} onSetPrimary={onSetPrimary} onDelete={onDeleteImage}/>
  </section>;
}

function PortfolioImageLibrary({features,images,busy,onUpload,onSetPrimary,onDelete}:{features:any[],images:any[],busy:boolean,onUpload:any,onSetPrimary:any,onDelete:any}){
  const [form,setForm]=useState({featureId:Number(features[0]?.id||0),caption:"",isPrimary:true,sortOrder:0,file:null as File|null});
  useEffect(()=>{if(!form.featureId&&features[0]?.id)setForm(old=>({...old,featureId:Number(features[0].id)}));},[features,form.featureId]);
  const submit=()=>{if(!form.file||!form.featureId)return;if(!["image/png","image/jpeg","image/webp"].includes(form.file.type)){toast.error("Selecione uma imagem PNG, JPEG ou WebP.");return;}if(form.file.size>12*1024*1024){toast.error("A imagem deve ter no máximo 12 MB.");return;}const reader=new FileReader();reader.onload=()=>onUpload({featureId:form.featureId,fileName:form.file!.name,mimeType:form.file!.type,base64:String(reader.result),caption:form.caption||undefined,sortOrder:form.sortOrder,isPrimary:form.isPrimary});reader.onerror=()=>toast.error("Não foi possível ler a imagem.");reader.readAsDataURL(form.file);};
  return <div className="border bg-white p-5"><div className="flex flex-col gap-2 md:flex-row md:items-start md:justify-between"><div><h3 className="font-semibold">Biblioteca de imagens do portfólio</h3><p className="text-sm text-muted-foreground">Salve prints por funcionalidade e marque a imagem padrão reutilizada no portfólio, propostas e catálogo.</p></div></div><div className="mt-4 grid gap-3 md:grid-cols-[1fr_1fr_150px_auto]"><label className="text-sm">Funcionalidade<select value={form.featureId||""} onChange={e=>setForm({...form,featureId:Number(e.target.value)})} className="mt-1 h-10 w-full border rounded-md bg-white px-3">{features.map(feature=><option key={feature.id} value={feature.id}>{feature.name}</option>)}</select></label><label className="text-sm">Imagem<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>setForm({...form,file:e.target.files?.[0]||null})} className="mt-1 h-10 w-full border rounded-md px-2 py-1.5"/></label><label className="text-sm">Ordem<Input type="number" min={0} value={form.sortOrder} onChange={e=>setForm({...form,sortOrder:Number(e.target.value)})}/></label><div className="flex items-end"><Button disabled={busy||!form.file||!form.featureId} onClick={submit}><Upload size={14}/>Enviar</Button></div><label className="text-sm md:col-span-3">Legenda<Input value={form.caption} onChange={e=>setForm({...form,caption:e.target.value})}/></label><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={form.isPrimary} onChange={e=>setForm({...form,isPrimary:e.target.checked})}/>Imagem padrão</label></div><div className="mt-5 grid sm:grid-cols-2 lg:grid-cols-4 gap-3">{images.map((image:any)=><article key={image.id} className="border"><div className="aspect-video bg-slate-100"><img src={image.image_url} alt={image.caption||image.feature_name} className="h-full w-full object-cover object-top"/></div><div className="p-3"><div className="flex items-start justify-between gap-2"><b className="text-sm">{image.feature_name}</b>{image.is_primary?<span className="text-xs font-semibold text-emerald-700">Padrão</span>:null}</div><p className="mt-1 text-xs text-muted-foreground min-h-8">{image.caption||image.original_name}</p><div className="mt-2 flex gap-2">{!image.is_primary&&<Button size="sm" variant="outline" disabled={busy} onClick={()=>onSetPrimary(Number(image.id))}>Definir padrão</Button>}<Button size="icon" variant="outline" disabled={busy} title="Excluir imagem" onClick={()=>{if(window.confirm("Excluir esta imagem da biblioteca?"))onDelete(Number(image.id));}}><Trash2 size={14}/></Button></div></div></article>)}{!images.length&&<div className="sm:col-span-2 lg:col-span-4 border border-dashed p-8 text-center text-sm text-muted-foreground">Nenhuma imagem cadastrada. O PDF usará o bloco visual padrão até que um print seja enviado.</div>}</div></div>;
}

function SendProposalModal({proposal,onClose,onConfirm,loading}:{proposal:any,onClose:any,onConfirm:any,loading:boolean}){return <Modal title="Confirmar envio da proposta" onClose={onClose}><div className="border-l-4 border-amber-500 bg-amber-50 p-4 text-sm text-amber-950"><b>Deseja realmente enviar esta proposta por e-mail?</b><p className="mt-1">O envio somente ocorrerá depois da confirmação abaixo.</p></div><dl className="mt-4 grid grid-cols-[100px_1fr] gap-y-2 text-sm"><dt className="text-muted-foreground">Cliente</dt><dd className="font-medium">{proposal.razao_social}</dd><dt className="text-muted-foreground">E-mail</dt><dd>{proposal.email||"Não informado"}</dd><dt className="text-muted-foreground">Proposta</dt><dd>{proposal.proposal_number||`#${proposal.id}`}</dd></dl><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={loading||!proposal.email} onClick={onConfirm}>{loading?<Loader2 size={14} className="animate-spin"/>:<Mail size={14}/>}Confirmar envio</Button></div></Modal>}

function CommercialStructureTab({data,onEditAddon,onSaveBands,saving}:{data:any,onEditAddon:any,onSaveBands:any,saving:boolean}){
  const [bands,setBands]=useState<any[]>([]);
  useEffect(()=>setBands((data?.bands||[]).map((row:any)=>({id:Number(row.id),label:row.label,minEmployees:Number(row.min_employees),maxEmployees:Number(row.max_employees),minimumMonthly:Number(row.minimum_monthly||0),discountPct:Number(row.discount_pct||0),sortOrder:Number(row.sort_order||0)}))),[data?.bands]);
  const update=(index:number,key:string,value:any)=>setBands(rows=>rows.map((row,i)=>i===index?{...row,[key]:value}:row));
  return <section className="space-y-6"><div><h2 className="font-semibold text-lg">17 pilares do catálogo técnico</h2><p className="text-sm text-muted-foreground">Estrutura comum da plataforma; planos, preços e disponibilidade permanecem independentes neste ambiente.</p><div className="mt-3 grid md:grid-cols-2 gap-2">{(data?.pillars||[]).map((p:any,index:number)=><div key={p.id} className="border bg-white p-3"><span className="text-xs font-bold text-primary">{String(index+1).padStart(2,"0")}</span><b className="ml-2 text-sm">{p.name}</b><div className="text-xs text-muted-foreground mt-1">{p.category}</div></div>)}</div></div>
  <div><div className="flex items-center justify-between"><div><h2 className="font-semibold text-lg">Add-ons</h2><p className="text-sm text-muted-foreground">Valores e modalidades são editáveis por rede.</p></div><Button onClick={()=>onEditAddon({})}><Plus size={14}/>Novo add-on</Button></div><div className="mt-3 grid md:grid-cols-2 gap-2">{(data?.addons||[]).map((a:any)=><button key={a.id} onClick={()=>onEditAddon(a)} className="text-left border bg-white p-3 hover:border-primary"><div className="flex justify-between gap-2"><b>{a.name}</b><span className="font-semibold text-primary">{brl(a.unit_price)}</span></div><p className="text-xs text-muted-foreground mt-1">{a.description}</p></button>)}</div></div>
  <div><h2 className="font-semibold text-lg">Faixas de colaboradores</h2><p className="text-sm text-muted-foreground">Defina mínimo mensal e desconto por faixa sem alterar o código.</p><div className="mt-3 overflow-x-auto border bg-white"><table className="w-full text-sm"><thead className="bg-slate-50"><tr><th className="p-2 text-left">Faixa</th><th className="p-2">Mínimo</th><th className="p-2">Máximo</th><th className="p-2">Mensalidade mínima</th><th className="p-2">Desconto %</th></tr></thead><tbody>{bands.map((b,index)=><tr key={b.id||index} className="border-t"><td className="p-2"><Input value={b.label} onChange={e=>update(index,"label",e.target.value)}/></td><td className="p-2"><Input type="number" value={b.minEmployees} onChange={e=>update(index,"minEmployees",Number(e.target.value))}/></td><td className="p-2"><Input type="number" value={b.maxEmployees} onChange={e=>update(index,"maxEmployees",Number(e.target.value))}/></td><td className="p-2"><Input type="number" value={b.minimumMonthly} onChange={e=>update(index,"minimumMonthly",Number(e.target.value))}/></td><td className="p-2"><Input type="number" value={b.discountPct} onChange={e=>update(index,"discountPct",Number(e.target.value))}/></td></tr>)}</tbody></table></div><Button className="mt-3" disabled={saving||!bands.length} onClick={()=>onSaveBands(bands)}>{saving?<Loader2 size={14} className="animate-spin"/>:<Save size={14}/>}Salvar faixas</Button></div></section>;
}

function AddonModal({initial,onClose,onSave,loading}:{initial:any,onClose:any,onSave:any,loading:boolean}){const [f,setF]=useState({id:initial.id,code:initial.code||"",name:initial.name||"",description:initial.description||"",billingMode:initial.billing_mode||"fixed",unitPrice:Number(initial.unit_price||0),setupPrice:Number(initial.setup_price||0),unitLabel:initial.unit_label||"",isActive:initial.is_active===undefined?true:Boolean(initial.is_active),sortOrder:Number(initial.sort_order||0)});const set=(k:string,v:any)=>setF({...f,[k]:v});return <Modal title={initial.id?"Editar add-on":"Novo add-on"} onClose={onClose}><div className="grid md:grid-cols-2 gap-3"><Field label="Nome"><Input value={f.name} onChange={e=>set("name",e.target.value)}/></Field><Field label="Código"><Input value={f.code} onChange={e=>set("code",e.target.value.toLowerCase().replace(/[^a-z0-9_]/g,"_"))}/></Field><Field label="Cobrança"><select className="w-full border rounded-md px-3 py-2" value={f.billingMode} onChange={e=>set("billingMode",e.target.value)}><option value="fixed">Valor fixo</option><option value="per_unit">Por unidade</option><option value="per_employee">Por colaborador</option><option value="per_cnpj">Por CNPJ</option></select></Field><Field label="Unidade"><Input value={f.unitLabel} onChange={e=>set("unitLabel",e.target.value)}/></Field><Field label="Valor"><Input type="number" value={f.unitPrice} onChange={e=>set("unitPrice",Number(e.target.value))}/></Field><Field label="Setup"><Input type="number" value={f.setupPrice} onChange={e=>set("setupPrice",Number(e.target.value))}/></Field><Field label="Descrição" wide><textarea className={area} value={f.description} onChange={e=>set("description",e.target.value)}/></Field></div><div className="mt-4 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={loading||!f.name||!f.code} onClick={()=>onSave(f)}><Save size={14}/>Salvar</Button></div></Modal>}

