function ProposalModalV2({initial,brand,plans,features,addons,bands,onClose,onSave,loading}:{initial:any,brand:any,plans:any[],features:any[],addons:any[],bands:any[],onClose:any,onSave:any,loading:boolean}){
  const parse=(value:any,fallback:any)=>{try{return JSON.parse(value||"")}catch{return fallback}};
  const savedIds:number[]=parse(initial.presented_plan_ids_json,[]).map(Number);
  const savedOverrides:any[]=parse(initial.plan_overrides_json,[]);
  const initialPresented=(savedIds.length?plans.filter(p=>savedIds.includes(Number(p.id))):plans).map(plan=>{
    const override=savedOverrides.find(x=>Number(x.planId)===Number(plan.id))||{};
    const employees=Number(override.employees??initial.qtd_colaboradores??0);
    const legacySelected=Number(initial.commercial_plan_id)===Number(plan.id)&&Number(initial.valor_mensal||0)>0;
    const monthlyValue=override.monthlyValue!=null?Number(override.monthlyValue):legacySelected?Number(initial.valor_mensal):commercialPrice(plan,employees,bands);
    const setupValue=override.setupValue!=null?Number(override.setupValue):legacySelected&&Number(initial.setup_value||0)>0?Number(initial.setup_value):Number(plan.setup_price||0);
    return {planId:Number(plan.id),monthlyValue,setupValue,employees,featureIds:Array.isArray(override.featureIds)?override.featureIds.map(Number):(plan.featureIds||[]),optionalFeatureIds:Array.isArray(override.optionalFeatureIds)?override.optionalFeatureIds.map(Number):[],limitsText:override.limitsText||""};
  });
  const [f,setF]=useState({id:initial.id,proposalTitle:initial.proposal_title||"Plataforma integrada de Saúde e Segurança do Trabalho",companyName:initial.razao_social||"",tradeName:initial.nome_fantasia||"",cnpj:initial.cnpj||"",cityState:initial.city_state||"",contactName:initial.responsavel||"",contactRole:initial.cargo||"",contactEmail:initial.email||"",contactPhone:initial.telefone||"",commercialOwnerName:initial.commercial_owner_name||"",firstContactDate:initial.first_contact_date?String(initial.first_contact_date).slice(0,10):null,meetingDate:initial.meeting_date?String(initial.meeting_date).slice(0,10):null,proposalSentDate:initial.proposal_sent_date?String(initial.proposal_sent_date).slice(0,10):null,nextContactDate:initial.next_contact_date?String(initial.next_contact_date).slice(0,10):null,lossReason:initial.loss_reason||"",selectedAddonIds:parse(initial.selected_addons_json,[]).map(Number),employees:Number(initial.qtd_colaboradores||0),presentedPlans:initialPresented,recommendedPlanId:initial.recommended_plan_id?Number(initial.recommended_plan_id):null,selectedPlanId:initial.selected_plan_id?Number(initial.selected_plan_id):null,selectedFeatureIds:features.map(x=>Number(x.id)),presentationText:initial.presentation_text||brand?.presentation_text||"",objectiveText:initial.objective_text||brand?.objective_text||"",setupValue:0,monthlyValue:0,discountValue:Number(initial.discount_value||0),discountPct:Number(initial.desconto_pct||0),services:parse(initial.services_json,[]),conditionsText:initial.conditions_text||brand?.commercial_terms||"",paymentTermsText:initial.payment_terms_text||"",implementationDays:initial.implementation_days==null?null:Number(initial.implementation_days),nextStepsText:initial.next_steps_text||brand?.next_steps_text||"",validityDays:Number(initial.validade_dias||15),status:initial.status||"novo_lead",notes:initial.observacoes||"",planId:null});
  const set=(k:string,v:any)=>setF({...f,[k]:v});
  const togglePlan=(plan:any,checked:boolean)=>setF({...f,presentedPlans:checked?[...f.presentedPlans,{planId:Number(plan.id),monthlyValue:commercialPrice(plan,f.employees,bands),setupValue:Number(plan.setup_price||0),employees:f.employees,featureIds:plan.featureIds||[],optionalFeatureIds:[],limitsText:""}]:f.presentedPlans.filter(x=>x.planId!==Number(plan.id)),recommendedPlanId:!checked&&f.recommendedPlanId===Number(plan.id)?null:f.recommendedPlanId,selectedPlanId:!checked&&f.selectedPlanId===Number(plan.id)?null:f.selectedPlanId});
  const updatePlan=(id:number,key:string,value:any)=>setF({...f,presentedPlans:f.presentedPlans.map(x=>x.planId===id?{...x,[key]:value}:x)});
  const updatePlanFeature=(planId:number,featureId:number,state:string)=>setF({...f,presentedPlans:f.presentedPlans.map(item=>item.planId!==planId?item:{...item,featureIds:state==="included"?[...item.featureIds.filter((id:number)=>id!==featureId),featureId]:item.featureIds.filter((id:number)=>id!==featureId),optionalFeatureIds:state==="optional"?[...item.optionalFeatureIds.filter((id:number)=>id!==featureId),featureId]:item.optionalFeatureIds.filter((id:number)=>id!==featureId)})});
  const setEmployees=(employees:number)=>setF({...f,employees,presentedPlans:f.presentedPlans.map(x=>{const plan=plans.find(p=>Number(p.id)===x.planId);return {...x,employees,monthlyValue:plan?commercialPrice(plan,employees,bands):x.monthlyValue}})});
  return <Modal title={initial.id?"Editar proposta":"Nova proposta"} onClose={onClose}>
    <div className="grid md:grid-cols-2 gap-3">
      <Field label="Título da proposta" wide><Input value={f.proposalTitle} onChange={e=>set("proposalTitle",e.target.value)}/></Field>
      <Field label="Empresa"><Input value={f.companyName} onChange={e=>set("companyName",e.target.value)}/></Field><Field label="CNPJ"><Input value={f.cnpj} onChange={e=>set("cnpj",e.target.value)}/></Field>
      <Field label="Cidade/UF"><Input value={f.cityState} onChange={e=>set("cityState",e.target.value)}/></Field><Field label="Responsável comercial"><Input value={f.commercialOwnerName} onChange={e=>set("commercialOwnerName",e.target.value)}/></Field>
      <Field label="Contato"><Input value={f.contactName} onChange={e=>set("contactName",e.target.value)}/></Field><Field label="Cargo do contato"><Input value={f.contactRole} onChange={e=>set("contactRole",e.target.value)}/></Field><Field label="E-mail"><Input value={f.contactEmail} onChange={e=>set("contactEmail",e.target.value)}/></Field><Field label="Telefone/WhatsApp"><Input value={f.contactPhone} onChange={e=>set("contactPhone",e.target.value)}/></Field>
      <Field label="Quantidade de colaboradores"><Input type="number" min={0} value={f.employees} onChange={e=>setEmployees(Number(e.target.value))}/></Field><Field label="Validade em dias"><Input type="number" value={f.validityDays} onChange={e=>set("validityDays",Number(e.target.value))}/></Field>
      <Field label="Apresentação" wide><textarea className={area} value={f.presentationText} onChange={e=>set("presentationText",e.target.value)}/></Field><Field label="Objetivo" wide><textarea className={area} value={f.objectiveText} onChange={e=>set("objectiveText",e.target.value)}/></Field>
      <Field label="Planos apresentados" wide><div className="space-y-3 border rounded-md p-3">{plans.map(plan=>{const item=f.presentedPlans.find(x=>x.planId===Number(plan.id));return <div key={plan.id} className="border p-3"><label className="flex gap-2 font-semibold"><input type="checkbox" checked={!!item} onChange={e=>togglePlan(plan,e.target.checked)}/>{plan.name}</label>{item&&<><div className="grid sm:grid-cols-3 gap-2 mt-3"><Field label="Mensalidade"><Input type="number" value={item.monthlyValue} onChange={e=>updatePlan(item.planId,"monthlyValue",Number(e.target.value))}/></Field><Field label="Setup"><Input type="number" value={item.setupValue} onChange={e=>updatePlan(item.planId,"setupValue",Number(e.target.value))}/></Field><Field label="Colaboradores"><Input type="number" value={item.employees} onChange={e=>updatePlan(item.planId,"employees",Number(e.target.value))}/></Field><Field label="Limites/premissas" wide><Input value={item.limitsText} onChange={e=>updatePlan(item.planId,"limitsText",e.target.value)}/></Field></div><details className="mt-3 border-t pt-3"><summary className="cursor-pointer text-sm font-semibold">Configurar funcionalidades deste plano</summary><div className="mt-3 grid md:grid-cols-2 gap-2 max-h-72 overflow-y-auto pr-1">{features.map(feature=>{const state=item.featureIds.includes(Number(feature.id))?"included":item.optionalFeatureIds.includes(Number(feature.id))?"optional":"excluded";return <label key={feature.id} className="flex items-center justify-between gap-2 border px-2 py-1.5 text-xs"><span>{feature.name}</span><select value={state} onChange={event=>updatePlanFeature(item.planId,Number(feature.id),event.target.value)} className="border rounded px-1 py-1 bg-white"><option value="included">Incluído</option><option value="optional">Adicional</option><option value="excluded">Não incluído</option></select></label>})}</div></details></>}</div>})}</div></Field>
      <Field label="Plano recomendado"><select className="w-full border rounded-md px-3 py-2" value={f.recommendedPlanId||""} onChange={e=>set("recommendedPlanId",e.target.value?Number(e.target.value):null)}><option value="">Nenhum</option>{f.presentedPlans.map(item=><option value={item.planId} key={item.planId}>{plans.find(p=>Number(p.id)===item.planId)?.name}</option>)}</select></Field>
      <Field label="Plano selecionado/contratado"><select className="w-full border rounded-md px-3 py-2" value={f.selectedPlanId||""} onChange={e=>set("selectedPlanId",e.target.value?Number(e.target.value):null)}><option value="">Ainda não selecionado</option>{f.presentedPlans.map(item=><option value={item.planId} key={item.planId}>{plans.find(p=>Number(p.id)===item.planId)?.name}</option>)}</select></Field>
      <Field label="Add-ons" wide><div className="grid sm:grid-cols-2 gap-2 border rounded-md p-3">{addons.filter(a=>Boolean(a.is_active)).map(a=><label key={a.id} className="flex items-start gap-2 text-sm"><input type="checkbox" checked={f.selectedAddonIds.includes(Number(a.id))} onChange={e=>set("selectedAddonIds",e.target.checked?[...f.selectedAddonIds,Number(a.id)]:f.selectedAddonIds.filter((id:number)=>id!==Number(a.id)))}/><span><b>{a.name}</b><small className="block text-muted-foreground">{brl(a.unit_price)}</small></span></label>)}</div></Field>
      <Field label="Serviços e custos adicionais" wide><div className="space-y-2 border rounded-md p-3"><Button size="sm" variant="outline" onClick={()=>set("services",[...f.services,{name:"",value:0,description:""}])}><Plus size={13}/>Adicionar serviço</Button>{f.services.map((service:any,index:number)=><div key={index} className="grid sm:grid-cols-[1fr_120px_1fr_auto] gap-2"><Input placeholder="Serviço" value={service.name} onChange={e=>set("services",f.services.map((x:any,i:number)=>i===index?{...x,name:e.target.value}:x))}/><Input type="number" placeholder="Valor" value={service.value} onChange={e=>set("services",f.services.map((x:any,i:number)=>i===index?{...x,value:Number(e.target.value)}:x))}/><Input placeholder="Descrição" value={service.description} onChange={e=>set("services",f.services.map((x:any,i:number)=>i===index?{...x,description:e.target.value}:x))}/><Button size="icon" variant="ghost" onClick={()=>set("services",f.services.filter((_:any,i:number)=>i!==index))}><X size={14}/></Button></div>)}</div></Field>
      <Field label="Prazo de implantação (dias)"><Input type="number" value={f.implementationDays??""} onChange={e=>set("implementationDays",e.target.value?Number(e.target.value):null)}/></Field><Field label="Desconto comercial"><Input type="number" value={f.discountValue} onChange={e=>set("discountValue",Number(e.target.value))}/></Field>
      <Field label="Status"><select className="w-full border rounded-md px-3 py-2" value={f.status} onChange={e=>set("status",e.target.value)}>{Object.entries(statusLabel).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></Field><Field label="Próximo contato"><Input type="date" value={f.nextContactDate||""} onChange={e=>set("nextContactDate",e.target.value||null)}/></Field>
      <Field label="Condições de pagamento" wide><textarea className={area} value={f.paymentTermsText} onChange={e=>set("paymentTermsText",e.target.value)}/></Field><Field label="Condições comerciais" wide><textarea className={area} value={f.conditionsText} onChange={e=>set("conditionsText",e.target.value)}/></Field><Field label="Próximos passos" wide><textarea className={area} value={f.nextStepsText} onChange={e=>set("nextStepsText",e.target.value)}/></Field>
    </div>
    <div className="mt-3 border-l-4 border-primary bg-slate-50 p-3 text-sm"><b>Conferência:</b> {f.presentedPlans.length} plano(s) serão apresentados. {f.recommendedPlanId?"Há uma recomendação comercial.":"Nenhum plano foi recomendado."} {f.selectedPlanId?"Um plano foi marcado como selecionado.":"O cliente ainda não escolheu um plano."}</div>
    <div className="flex justify-end gap-2 mt-4"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={!f.companyName||!f.proposalTitle||!f.presentedPlans.length||loading} onClick={()=>onSave(f)}>{loading?<Loader2 size={14} className="animate-spin"/>:<Save size={14}/>}Salvar proposta</Button></div>
  </Modal>
}

function FinanceTab({data,onPaid}:{data:any,onPaid:any}){const rows=data?.receivables||[];return <section className="space-y-4"><div className="grid sm:grid-cols-3 gap-3"><Metric label="Contratos" value={data?.contracts?.length||0}/><Metric label="Recebíveis" value={rows.length}/><Metric label="Em aberto" value={brl(rows.filter((x:any)=>['pendente','atrasado'].includes(x.status)).reduce((s:number,x:any)=>s+Number(x.amount||0),0))}/></div><div className="overflow-x-auto border rounded-md bg-white"><table className="w-full text-sm"><thead className="bg-slate-50"><tr><th className="p-3 text-left">Cliente</th><th className="p-3">Referência</th><th className="p-3 text-right">Valor</th><th className="p-3">Vencimento</th><th className="p-3">Status</th><th className="p-3"></th></tr></thead><tbody>{rows.map((r:any)=><tr key={r.id} className="border-t"><td className="p-3">{r.company_name}</td><td className="p-3 text-center">{r.reference_month} · {r.kind}</td><td className="p-3 text-right font-semibold">{brl(r.amount)}</td><td className="p-3 text-center">{r.due_date?new Date(r.due_date).toLocaleDateString("pt-BR"):"-"}</td><td className="p-3 text-center">{r.status}</td><td className="p-3 text-right">{r.status!=="recebido"&&<Button size="sm" variant="outline" onClick={()=>onPaid(Number(r.id))}>Marcar recebido</Button>}</td></tr>)}</tbody></table>{!rows.length&&<Empty text="Nenhum recebível. Aprove uma proposta para criar o contrato e o cronograma financeiro."/>}</div></section>}
